begin;
select plan(21);
insert into auth.users(id,email) values
 ('77777777-7777-4777-8777-777777777771','selection@example.test'),
 ('77777777-7777-4777-8777-777777777772','other-selection@example.test');
select public.get_or_create_account_profile('77777777-7777-4777-8777-777777777771','selection@example.test',true);
select public.get_or_create_account_profile('77777777-7777-4777-8777-777777777772','other-selection@example.test',true);
select public.submit_search_items('77777777-7777-4777-8777-777777777771',array['https://primary.example/selection']);
create temporary table selection_job as select * from public.claim_processing_job('77777777-7777-4777-8777-777777777771');
select public.save_job_source(user_id,id,lease_token,repeat('Primary topic evidence ',30)) from selection_job;
select is((select count(*)::int from selection_job j cross join lateral public.reserve_source_selection(j.user_id,j.id,j.lease_token,0.02688)),0,'confirmed settled search is required');
create temporary table selection_search as select r.* from selection_job j cross join lateral public.reserve_web_search(j.user_id,j.id,j.lease_token,0.005) r;
select public.settle_analysis(user_id,id,0.005) from selection_search;
select is((select count(*)::int from selection_job j cross join lateral public.reserve_source_selection('77777777-7777-4777-8777-777777777772',j.id,j.lease_token,0.02688)),0,'admin cannot classify another owners candidates');
select is((select count(*)::int from selection_job j cross join lateral public.reserve_source_selection(j.user_id,j.id,gen_random_uuid(),0.02688)),0,'stale lease cannot reserve selection');
select throws_ok($$select public.reserve_source_selection('77777777-7777-4777-8777-777777777771',gen_random_uuid(),gen_random_uuid(),0)$$,'22023',null,'invalid amount rejected');
update public.items set expires_at=now()-interval '1 second' where id=(select item_id from selection_job);
select is((select count(*)::int from selection_job j cross join lateral public.reserve_source_selection(j.user_id,j.id,j.lease_token,0.02688)),0,'expired content cannot classify');
update public.items set expires_at=now()+interval '1 day' where id=(select item_id from selection_job);
update public.account_profiles set status='rejected' where user_id='77777777-7777-4777-8777-777777777771';
select is((select count(*)::int from selection_job j cross join lateral public.reserve_source_selection(j.user_id,j.id,j.lease_token,0.02688)),0,'rejected account cannot classify');
update public.account_profiles set status='approved' where user_id='77777777-7777-4777-8777-777777777771';
select public.set_user_budget('77777777-7777-4777-8777-777777777771',0.01);
select is((select count(*)::int from selection_job j cross join lateral public.reserve_source_selection(j.user_id,j.id,j.lease_token,0.02688)),0,'shared budget blocks selection');
select public.set_user_budget('77777777-7777-4777-8777-777777777771',10);
create temporary table selection_res as select r.id from selection_job j cross join lateral public.reserve_source_selection(j.user_id,j.id,j.lease_token,0.02688) r;
select is((select count(*)::int from selection_res),1,'one selection admitted');
select is((select count(*)::int from selection_job j cross join lateral public.reserve_source_selection(j.user_id,j.id,j.lease_token,0.02688)),0,'same slot cannot be returned twice');
select is((select purpose from public.usage_reservations where id=(select id from selection_res)),'source_selection','distinct selection purpose');
select is((select reserved_usd from public.get_usage_summary('77777777-7777-4777-8777-777777777771')),0.02688::numeric,'selection holds consume shared budget');
update public.jobs set lease_expires_at=now()-interval '1 second' where id=(select id from selection_job);
create temporary table selection_reclaimed as select * from public.claim_processing_job('77777777-7777-4777-8777-777777777771');
select is((select selection_reservation_id from selection_reclaimed),(select id from selection_res),'recovery exposes prior selection slot');
select is((select count(*)::int from selection_job j cross join selection_res r cross join lateral public.record_source_selection_generation(j.user_id,j.id,r.id,'selection-gen')),1,'generation recording survives stale lease');
select is((select count(*)::int from selection_job j cross join selection_res r cross join lateral public.record_source_selection_generation('77777777-7777-4777-8777-777777777772',j.id,r.id,'foreign')),0,'foreign owner cannot record');
select is((select count(*)::int from selection_job j cross join selection_res r cross join lateral public.record_source_selection_generation(j.user_id,j.id,r.id,'replacement')),0,'generation cannot be overwritten');
select public.settle_analysis('77777777-7777-4777-8777-777777777771',(select id from selection_res),0.0001);
select is((select spent_usd from public.get_usage_summary('77777777-7777-4777-8777-777777777771')),0.0051::numeric,'actual selection cost adds to search cost');
select is((select count(*)::int from selection_reclaimed j cross join lateral public.reserve_source_selection(j.user_id,j.id,j.lease_token,0.02688)),0,'settled slot is not resent');
select public.delete_items('77777777-7777-4777-8777-777777777771',array[(select item_id from selection_job)],true);
select ok((select job_id is null from public.usage_reservations where id=(select id from selection_res)),'deletion retains selection accounting');
select is((select count(*)::int from selection_job j cross join selection_res r cross join lateral public.record_source_selection_generation(j.user_id,j.id,r.id,'selection-gen')),1,'late generation can be retained after deletion');
set local role authenticated;
select throws_ok($$select public.reserve_source_selection('77777777-7777-4777-8777-777777777771',gen_random_uuid(),gen_random_uuid(),0.02688)$$,'42501',null,'selection admission is server only');
select throws_ok($$select public.record_source_selection_generation('77777777-7777-4777-8777-777777777771',gen_random_uuid(),gen_random_uuid(),'gen')$$,'42501',null,'selection accounting is server only');
reset role;
select * from finish();
rollback;
